/// <summary>
/// This is the data contract class for the price list ER report
/// </summary>
[DataContractAttribute]
public class AVAERPriceListContract extends ERFormatMappingRunBaseContract
{
    str packedQuery;
    public boolean     printToMemory;

}

Method.Source:
/// <summary>
/// parm method for packedQuery
/// </summary>
/// <param name = "_packedQuery">str</param>
/// <returns>str</returns>
[DataMemberAttribute, AifQueryTypeAttribute('_packedQuery', queryStr(AVAERPriceList))]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}

public boolean parmPrintToMemory(boolean        _printToMemory = printToMemory)
{
    printToMemory = _printToMemory;
    return printToMemory;
}

// This method unpacks the query and returns it as query object.
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

// This method takes a query object, encodes it and stores the packed query.
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}

/// <summary>
/// initFromArgs method
/// </summary>
/// <param name = "_args">Args</param>
public void initFromArgs(Args _args)
{
    FormRun formRun = _args.caller();
    FormDataSource fds_priceDiscGroup = formRun.dataSource();
    MultiSelectionHelper helper = MultiSelectionHelper::construct();
    PriceDiscGroup priceDiscGroup;

    helper.parmDatasource(fds_priceDiscGroup);

    //FormDataSource fds_priceList = FormDataUtil::getFormDataSource(_args.record());
    //Query query = this.getQuery();
    Query query = new Query(queryStr(AVAERPriceList));
    QueryBuildDataSource qbdsPRiceDiscGroup = query.dataSourceTable(tablenum(PriceDiscGroup));
    QueryBuildRange qbrPriceDiscId = qbdsPRiceDiscGroup.addRange(FieldNum(PriceDiscGroup, GroupId));

    priceDiscGroup = helper.getFirst();
    while (priceDiscGroup.RecId != 0)
    {
        qbrPriceDiscId.value(queryRangeConcat(qbrPriceDiscId.value(), priceDiscGroup.GroupId));
        priceDiscGroup = helper.getNext();
    }

    this.setQuery(query);       
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_priceGroupId">_priceGroupId</param>
public void initFromPriceGroup(PriceGroupId    _priceGroupId)
{
    Query query = new Query(queryStr(AVAERPriceList));
    QueryBuildDataSource qbdsPRiceDiscGroup = query.dataSourceTable(tablenum(PriceDiscGroup));
    QueryBuildRange qbrPriceDiscId = qbdsPRiceDiscGroup.addRange(FieldNum(PriceDiscGroup, GroupId));

    qbrPriceDiscId.value(_priceGroupId);

    this.setQuery(query);
}
